import{_ as r,o as a,c as s,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Days Asia- Scrub / Deep-scrub Analysis.","description":"","frontmatter":{"title":"Ceph Days Asia- Scrub / Deep-scrub Analysis.","date":"2024-11-05T00:00:00.000Z","updated":"2024-11-06T00:00:00.000Z","tags":["Ceph","Distributed Storage","Data Integrity","scrub","deep scrub"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_Days_Asia_-_Scrub_Deep-scrub_Analysis..md","filePath":"posts/2024/Ceph_Days_Asia_-_Scrub_Deep-scrub_Analysis..md","lastUpdated":1780459816000}'),i={name:"posts/2024/Ceph_Days_Asia_-_Scrub_Deep-scrub_Analysis..md"};function o(t,e,u,n,c,p){return a(),s("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph存储系统中的scrub和deep-scrub机制及优化策略" tabindex="-1">会议主题：Ceph存储系统中的scrub和deep scrub机制及优化策略 <a class="header-anchor" href="#会议主题-ceph存储系统中的scrub和deep-scrub机制及优化策略" aria-label="Permalink to &quot;会议主题：Ceph存储系统中的scrub和deep scrub机制及优化策略&quot;">​</a></h4><h4 id="会议时间-具体日期" tabindex="-1">会议时间：[具体日期] <a class="header-anchor" href="#会议时间-具体日期" aria-label="Permalink to &quot;会议时间：[具体日期]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="参会人员-jae-min-jae-min-三星sds-、chaplain、jeong-soon-yong等" tabindex="-1">参会人员：Jae-min Jae-min（三星SDS）、Chaplain、Jeong Soon-Yong等 <a class="header-anchor" href="#参会人员-jae-min-jae-min-三星sds-、chaplain、jeong-soon-yong等" aria-label="Permalink to &quot;参会人员：Jae-min Jae-min（三星SDS）、Chaplain、Jeong Soon-Yong等&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>公司介绍</strong>：</p><ul><li>三星SDS是三星集团内的IT服务公司，主要负责创建和运营数据系统。</li><li>公司拥有两个主要平台：SCP（类似AWS）和Cello Square（现称为Diro Service）。</li><li>公司在全球40个国家设有58个分支机构和18个数据中心，服务于众多国际和国内客户。</li></ul></li><li><p><strong>scrub和deep scrub概念介绍</strong>：</p><ul><li><strong>scrub</strong>：检查和比较元数据区域，确保数据的完整性和一致性。</li><li><strong>deep scrub</strong>：在块级别进行更深入的检查，验证数据的存在和复制数量。</li></ul></li><li><p><strong>scrub和deep scrub的重要性</strong>：</p><ul><li>预防因磁盘故障、软件损坏、服务器故障等问题导致的数据完整性受损。</li><li>通过定期执行scrub和deep scrub，可以在问题变得严重之前识别并解决。</li></ul></li><li><p><strong>测试结果展示</strong>：</p><ul><li>测试环境：Ceph集群包含六个主机，每个主机上部署了多个OSD、mgr和MON。</li><li>测试配置：调整了OSD Max Scrubs、OSD Scrub Load Threshold等参数。</li><li>测试结果：增加scrub和deep scrub的数量和大小会导致客户端IO性能下降，执行时间延长。</li></ul></li><li><p><strong>优化策略讨论</strong>：</p><ul><li><strong>减少scrub运行次数</strong>：通过调整OSD scrub lander&#39;s race和OSD scrub load tread值。</li><li><strong>降低scrub性能</strong>：减少OSD scrub chunk max size和OSD scrub stride值。</li><li><strong>调整scrub执行频率</strong>：通过增加OSD Scrum Max Interval和OSD Scrum Sleep值。</li><li><strong>基于集群状态和环境优化</strong>：根据集群负载、数据故障率和操作时间进行调整。</li></ul></li><li><p><strong>Ceph配置和代码分析</strong>：</p><ul><li>分析了OSD Deep Scrub Randomizer Ratio和OSD Scrub Load Threshold的配置和代码实现。</li><li>讨论了配置设置与实际执行之间的差异，以及如何通过代码调整来优化scrub和deep scrub的执行。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>继续优化scrub和deep scrub的配置，确保数据完整性和性能平衡。</li><li>开发工具和脚本，以便更有效地管理和监控scrub和deep scrub的执行。</li><li>分享测试结果和优化策略，帮助其他集群进行类似的优化。</li></ul></li></ol><h4 id="会议结论" tabindex="-1">会议结论： <a class="header-anchor" href="#会议结论" aria-label="Permalink to &quot;会议结论：&quot;">​</a></h4><ul><li>scrub和deep scrub是确保Ceph存储系统数据完整性的关键任务，但它们对客户端性能有显著影响。</li><li>需要根据集群的具体状态和环境，不断优化scrub和deep scrub的设置和执行策略。</li><li>三星SDS将继续研究和分享相关优化策略，帮助用户更好地管理和优化其Ceph存储系统。</li></ul><h4 id="后续行动" tabindex="-1">后续行动： <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动：&quot;">​</a></h4><ul><li>继续监控和调整scrub和deep scrub的配置。</li><li>开发和分享更多的工具和脚本，以便用户更有效地管理scrub和deep scrub。</li><li>定期回顾和更新优化策略，确保其适应不断变化的集群环境和需求。</li></ul><p>以上是本次会议的详细纪要，涵盖了会议的主要议题、讨论内容、决定的事项以及后续的行动计划。希望这些信息对您有所帮助。</p>',12)])])}const h=r(i,[["render",o]]);export{d as __pageData,h as default};
